 说明： process 对象是一个全局对象（无需 require），提供有关当前 Node.js 进程的信息并对其进行控制。 常用属性/方法： process.argv: 返回一个数组，包含启动 Node.js 进程时的命令行参数。第一个元素是 node 可执行文件路径，第二个元素是当前 JS 文件路径，后续元素是传递的其他参数。process.env: 返回一个包含用户环境信息的对象（如 PATH, HOME）。注意： 敏感信息（如 API 密钥）应通过更安全的方式管理，而不是直接硬编码或放在 .env 文件中提交。process.cwd(): 返回当前 Node.js 进程的工作目录。process.pid: 当前进程的 ID。process.platform: 返回运行进程的操作系统平台（同 os.platform()）。process.arch: 返回运行进程的 CPU 架构（同 os.arch()）。process.version: Node.js 版本字符串。process.versions: 包含 Node.js 及其依赖（如 V8, libuv, OpenSSL）版本信息的对象。process.exit([code]): 以指定的状态码 code 退出当前进程（0 表示成功，非 0 表示错误）。process.nextTick(callback[, ...args]): 将回调函数添加到 nextTick 队列，在当前操作完成后、事件循环下一阶段开始前执行。process.on(eventName, listener): 监听进程事件，如： 'exit': 进程即将退出时触发（在此回调中不能执行异步操作）。'uncaughtException': 当一个未被捕获的 JavaScript 异常冒泡回事件循环时触发。不推荐用它来恢复应用正常运行，主要用于执行同步清理或记录日志。'unhandledRejection': 当一个 Promise 被 reject 且没有 catch 处理时触发。信号事件 (如 'SIGINT', 'SIGTERM'): 处理操作系统信号。 process.stdout, process.stderr, process.stdin: 分别代表标准输出、标准错误、标准输入的流对象。console.log 内部就是使用 process.stdout。 示例： // 获取命令行参数 console.log(&quot;Command line arguments:&quot;, process.argv); // Run: node your_script.js arg1 arg2 // Output: [ '/path/to/node', '/path/to/your_script.js', 'arg1', 'arg2' ] // 获取环境变量 console.log( &quot;Current PATH:&quot;, process.env.PATH ? process.env.PATH.substring(0, 50) + &quot;...&quot; : &quot;N/A&quot; ); console.log(&quot;NODE_ENV:&quot;, process.env.NODE_ENV || &quot;development&quot;); // 常用于区分环境 // 获取进程信息 console.log(&quot;Current working directory:&quot;, process.cwd()); console.log(&quot;Process ID:&quot;, process.pid); console.log(&quot;Node.js version:&quot;, process.version); // console.log('All versions:', process.versions); // 监听退出事件 process.on(&quot;exit&quot;, (code) =&gt; { // 只能执行同步操作 console.log(`
Process exiting with code: ${code}`); }); // 监听未捕获异常 (应谨慎使用) process.on(&quot;uncaughtException&quot;, (err, origin) =&gt; { console.error(`
Caught exception: ${err}
Exception origin: ${origin}`); // 在这里记录日志、清理资源，然后通常应该退出 process.exit(1); // 强制退出 }); // 监听未处理的 Promise rejection process.on(&quot;unhandledRejection&quot;, (reason, promise) =&gt; { console.error(&quot;
Unhandled Rejection at:&quot;, promise, &quot;reason:&quot;, reason); // 记录日志，可能也需要退出 // process.exit(1); }); // 模拟未捕获异常 // throw new Error('This is an uncaught exception!'); // 模拟未处理的 rejection // Promise.reject(new Error('This is an unhandled rejection!')); // 正常退出 (如果上面的模拟被注释掉) // setTimeout(() =&gt; { // console.log('
Exiting normally...'); // process.exit(0); // }, 1000); console.log(&quot;Script continues...&quot;);

 说明： Node.js 是单线程的（指 JS 执行），为了充分利用多核 CPU 或执行外部命令，child_process 模块允许你创建子进程。 创建子进程的方式： child_process.exec(command[, options][, callback]): 启动一个 shell 来执行 command。它会缓冲命令的输出，并在子进程完成后通过回调函数一次性返回 stdout 和 stderr。适合执行简单的命令，但对大量输出不友好（可能耗尽内存）。child_process.execFile(file[, args][, options][, callback]): 类似 exec，但不启动 shell，直接执行 file。更安全高效，适合执行特定可执行文件。child_process.spawn(command[, args][, options]): 启动一个新进程来执行 command。它不缓冲输出，而是通过流（stdout, stderr）来处理输入输出。适合处理大量数据或需要与子进程持续交互的场景。返回一个 ChildProcess 实例。child_process.fork(modulePath[, args][, options]): spawn 的特殊形式，专门用于创建新的 Node.js 进程。父子进程之间可以通过 send() 方法和 message 事件建立 IPC (Inter-Process Communication) 通道进行通信。 ChildProcess 实例事件/属性： stdout: 子进程的标准输出流 (Readable Stream)。stderr: 子进程的标准错误流 (Readable Stream)。stdin: 子进程的标准输入流 (Writable Stream)。pid: 子进程的 PID。on('message', (message) =&gt; ...): (仅 fork) 接收子进程通过 process.send() 发送的消息。on('error', (error) =&gt; ...): 进程无法被衍生或被杀死时触发。on('exit', (code, signal) =&gt; ...): 子进程退出时触发。on('close', (code, signal) =&gt; ...): 子进程所有 stdio 流都关闭后触发。send(message): (仅 fork) 向子进程发送消息。kill([signal]): 向子进程发送信号（默认 'SIGTERM'）。 示例： const { exec, spawn } = require(&quot;child_process&quot;); // 1. 使用 exec (简单命令，缓冲输出) console.log(&quot;--- Using exec ---&quot;); exec(&quot;ls -lh /usr&quot;, (error, stdout, stderr) =&gt; { if (error) { console.error(`exec error: ${error}`); return; } if (stderr) { console.error(`exec stderr: ${stderr}`); } console.log( `exec stdout (first 200 chars):
${stdout.substring(0, 200)}...` ); }); // 2. 使用 spawn (流式处理，适合大数据/交互) console.log(&quot;
--- Using spawn ---&quot;); const findProcess = spawn(&quot;find&quot;, [__dirname, &quot;-type&quot;, &quot;f&quot;]); // 执行 find 命令 let fileCount = 0; // 监听 stdout 流 findProcess.stdout.on(&quot;data&quot;, (data) =&gt; { const lines = data .toString() .split(&quot;
&quot;) .filter((line) =&gt; line.length &gt; 0); fileCount += lines.length; console.log(`spawn stdout chunk:
${lines.join(&quot;
&quot;)}`); }); // 监听 stderr 流 findProcess.stderr.on(&quot;data&quot;, (data) =&gt; { console.error(`spawn stderr: ${data}`); }); // 监听错误事件 findProcess.on(&quot;error&quot;, (err) =&gt; { console.error(&quot;Failed to start subprocess.&quot;, err); }); // 监听退出事件 findProcess.on(&quot;exit&quot;, (code, signal) =&gt; { if (code !== null) { console.log(`
spawn process exited with code ${code}`); console.log(`Total files found: ${fileCount}`); } else if (signal !== null) { console.log(`
spawn process killed with signal ${signal}`); } }); // // 3. 使用 fork (Node.js 子进程与 IPC 通信) // console.log('
--- Using fork ---'); // const worker = fork(require.resolve('./worker.js')); // 使用 require.resolve 获取绝对路径 // worker.on('message', (msg) =&gt; { // console.log('Message from worker:', msg); // if (msg.type === 'done') { // worker.kill(); // 任务完成，结束子进程 // } // }); // worker.on('exit', (code) =&gt; { // console.log(`Worker process exited with code ${code}`); // }); // worker.send({ type: 'start', payload: 10 }); // 向子进程发送消息 // // worker.js (子进程文件) // process.on('message', (msg) =&gt; { // console.log('[Worker] Received message:', msg); // if (msg.type === 'start') { // let result = 0; // for (let i = 0; i &lt; msg.payload * 100000000; i++) { // 模拟耗时计算 // result += i; // } // process.send({ type: 'done', result }); // 向父进程发送结果 // } // });
